INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'I think a good friend is like a mirror.', '我认为好朋友就像一面镜子。', 'I think ... is like ...', '经典句型 be like', '八上 U3 Section B 1b', 14, '经典句型', '基础句型与其它', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'You can understand people by knowing their friends.', '观其友，知其人。', 'by doing', '介词 by + doing 表方式', '八上 U3 Section B 1b', 15, '经典句型', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'We often hang out together because we have similar hobbies and interests.', '我们经常一起出去玩，因为我们有相似的爱好和兴趣。', 'hang out', '固定搭配 hang out；hobbies and interests（教材固定语序）', '八上 U3 Section B 1b', 16, '常用搭配', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'He plays badminton better than I do, so he always wins our matches.', '他打羽毛球比我好，所以比赛总是他赢。', '比较级 + than', '副词比较级；动词 + 比较级 + than', '八上 U3 Section B 1b', 17, '重点考点', '比较等级·比较级', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'Because of that, I try harder when I practise, and now I''m getting better at badminton.', '正因为如此，我练习时更努力，现在羽毛球打得越来越好。', 'because of; get better at', '固定搭配 because of；get better at', '八上 U3 Section B 1b', 18, '常用搭配', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'Stephen and I are similar in other ways.', '我和斯蒂芬在其他方面也很相似。', 'be similar in other ways', '固定搭配 in other ways', '八上 U3 Section B 1b', 19, '常用搭配', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'When we aren''t playing sports, we enjoy reading together.', '我们不运动时喜欢一起读书。', 'enjoy doing', '固定搭配 enjoy doing', '八上 U3 Section B 1b', 20, '常用搭配', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'I read more history books than he does, and he reads a lot of novels.', '我读的历史书比他多，他读很多小说。', '比较级 + than', '比较级 more', '八上 U3 Section B 1b', 21, '重点考点', '比较等级·比较级', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'We often share interesting books with each other.', '我们经常互相分享有趣的书。', 'share sth with each other', '固定搭配 share ... with each other', '八上 U3 Section B 1b', 22, '常用搭配', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'For me, friends who are different make me better.', '对我来说，不同的朋友让我变得更好。', 'who 引导定语从句', '定语从句', '八上 U3 Section B 1b', 23, '经典句型', '从句（宾语/定语/状语）', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'I think we should respect each other''s differences and learn from each other.', '我认为我们应该尊重彼此的差异，互相学习。', 'respect ...; learn from ...', '固定搭配 respect；learn from', '八上 U3 Section B 1b', 24, '常用搭配', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'I am kind of shy, but my best friend, Yuan Lei, is outgoing.', '我有点害羞，但我最好的朋友袁蕾很外向。', 'kind of + adj.', '固定搭配 kind of', '八上 U3 Section B 1b', 25, '常用搭配', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'She has a great sense of humour too.', '她也很有幽默感。', 'have a sense of humour', '固定搭配 a sense of humour', '八上 U3 Section B 1b', 26, '常用搭配', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'Thanks to her, I am becoming more outgoing.', '多亏了她，我变得更外向了。', 'Thanks to ...', '固定搭配 thanks to（归功于；由于）', '八上 U3 Section B 1b', 27, '常用搭配', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'He is not afraid to give his opinion, especially when he thinks I am making a mistake.', '他不怕发表看法，尤其当他觉得我在犯错时。', 'give one''s opinion; make a mistake', '固定搭配 give one''s opinion；make a mistake', '八上 U3 Section B 1b', 28, '常用搭配', '固定搭配与动词短语', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'I am less straightforward than he is, but I am glad to have an honest friend.', '我不如他直率，但我很高兴有一个诚实的朋友。', 'less + 原级 + than', '比较级 less ... than（不如……）', '八上 U3 Section B 1b', 29, '重点考点', '比较等级·比较级', 0);
INSERT INTO sentences (lesson_id, en, zh, pattern, grammar_point, source, sort_order, category, exam_point, is_review) VALUES (84, 'Now I think meeting new people is really fun!', '现在我觉得认识新的人真的很有趣！', '动名词作主语', '动名词（短语）作主语', '八上 U3 Section B 1b', 30, '经典句型', '基础句型与其它', 0);
INSERT INTO sentence_drills (id, sentence_id, exam_point, kind, prompt, answer, hint, sort_order) VALUES ('dr_u3_2', (SELECT id FROM sentences WHERE en = 'We often hang out together because we have similar hobbies and interests.' AND lesson_id = 84), '固定搭配与动词短语', 'cloze', 'We often ____ together because we have similar hobbies and interests.', 'hang out', 'hang out 闲逛；常去某处', 102);
INSERT INTO sentence_drills (id, sentence_id, exam_point, kind, prompt, answer, hint, sort_order) VALUES ('dr_u3_4', (SELECT id FROM sentences WHERE en = 'Because of that, I try harder when I practise, and now I''m getting better at badminton.' AND lesson_id = 84), '固定搭配与动词短语', 'cloze', '____ that, I try harder when I practise, and now I''m getting better at badminton.', 'Because of', 'because of 因为；由于（后接名词/代词，不接句子）', 104);
INSERT INTO sentence_drills (id, sentence_id, exam_point, kind, prompt, answer, hint, sort_order) VALUES ('dr_u3_5', (SELECT id FROM sentences WHERE en = 'Stephen and I are similar in other ways.' AND lesson_id = 84), '固定搭配与动词短语', 'cloze', 'Stephen and I are similar ____.', 'in other ways', 'in other ways 在其他方面', 105);
INSERT INTO sentence_drills (id, sentence_id, exam_point, kind, prompt, answer, hint, sort_order) VALUES ('dr_u3_8', (SELECT id FROM sentences WHERE en = 'We often share interesting books with each other.' AND lesson_id = 84), '固定搭配与动词短语', 'cloze', 'We often share interesting books ____.', 'with each other', 'share ... with each other 与……相互分享', 108);
INSERT INTO sentence_drills (id, sentence_id, exam_point, kind, prompt, answer, hint, sort_order) VALUES ('dr_u3_10', (SELECT id FROM sentences WHERE en = 'I think we should respect each other''s differences and learn from each other.' AND lesson_id = 84), '固定搭配与动词短语', 'cloze', 'I think we should respect each other''s differences and ____ each other.', 'learn from', 'learn from each other 互相学习', 110);
INSERT INTO sentence_drills (id, sentence_id, exam_point, kind, prompt, answer, hint, sort_order) VALUES ('dr_u3_11', (SELECT id FROM sentences WHERE en = 'I am kind of shy, but my best friend, Yuan Lei, is outgoing.' AND lesson_id = 84), '固定搭配与动词短语', 'cloze', 'I am ____ shy, but my best friend, Yuan Lei, is outgoing.', 'kind of', 'kind of 有点儿；稍微（后接形容词）', 111);
INSERT INTO sentence_drills (id, sentence_id, exam_point, kind, prompt, answer, hint, sort_order) VALUES ('dr_u3_12', (SELECT id FROM sentences WHERE en = 'She has a great sense of humour too.' AND lesson_id = 84), '固定搭配与动词短语', 'cloze', 'She has ____ too.', 'a great sense of humour', 'have a sense of humour 有幽默感', 112);
INSERT INTO sentence_drills (id, sentence_id, exam_point, kind, prompt, answer, hint, sort_order) VALUES ('dr_u3_13', (SELECT id FROM sentences WHERE en = 'Thanks to her, I am becoming more outgoing.' AND lesson_id = 84), '固定搭配与动词短语', 'cloze', '____ her, I am becoming more outgoing.', 'Thanks to', 'thanks to 归功于；由于；因为', 113);
INSERT INTO sentence_drills (id, sentence_id, exam_point, kind, prompt, answer, hint, sort_order) VALUES ('dr_u3_14', (SELECT id FROM sentences WHERE en = 'He is not afraid to give his opinion, especially when he thinks I am making a mistake.' AND lesson_id = 84), '固定搭配与动词短语', 'cloze', 'He is not afraid to ____, especially when he thinks I am making a mistake.', 'give his opinion', 'give one''s opinion 发表看法；表达观点', 114);
